const scores = [0, 5, 8, 10, 2.5, 3.75, 4.25, 6.5, 7.25, 8.5, 9.25, 9.75];
const hometowns = ['Hà Nội', 'TP. Hồ Chí Minh', 'Đà Nẵng', 'Cần Thơ', 'Hải Phòng', 'Nghệ An'];
const genders = ['Nam', 'Nữ', 'Khác'];
const ethnicities = ['Kinh', 'Tày', 'Thái', 'Mường', 'Khmer'];

// Mirrors the deterministic 60-row sample generated by database/site1/06_seed_data.sql.
export const students = Array.from({ length: 60 }, (_, index) => {
  const n = index + 1;
  return {
    MA: 'TST' + String(n).padStart(3, '0'),
    HT: 'Sinh viên ' + n,
    QQ: hometowns[n % 6],
    NS: 2000 + (n % 10),
    GT: genders[n % 3],
    DT: ethnicities[n % 5],
    TB: scores[n % 12],
  };
});

export const studentRows = students.map(student => [
  student.MA, student.HT, student.QQ, student.NS, student.GT, student.TB.toFixed(2),
]);
